import React from "react";

export default function EmployeTable({ employes }) {
    return (
        <table className="min-w-full border border-gray-300">
            <thead className="bg-gray-200">
            <tr>
                <th className="border p-2">ID</th>
                <th className="border p-2">Nom</th>
                <th className="border p-2">Rôle</th>
                <th className="border p-2">Disponible</th>
            </tr>
            </thead>
            <tbody>
            {employes.map(e => (
                <tr key={e.id}>
                    <td className="border p-2">{e.id}</td>
                    <td className="border p-2">{e.nom}</td>
                    <td className="border p-2">{e.role}</td>
                    <td className="border p-2">{e.disponible ? "Oui" : "Non"}</td>
                </tr>
            ))}
            </tbody>
        </table>
    );
}
